import type { ActionHeaderProps } from "./action-header.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "ActionHeader";

// Generate child element class names for the component, should match available style slots
export const ActionHeaderClasses = {
  root: "exp-textura_action-header",
  leading: "exp-textura_action-header_leading",
  center: "exp-textura_action-header_center",
  trailing: "exp-textura_action-header_trailing",
  divider: "exp-textura_action-header_divider",
  status: "exp-textura_action-header_status",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   default: {
//     // Add default variant styles here if needed in the future
//   },
// });

const generateStyles = (props: ActionHeaderProps): CSSObject => {
  const { currentTheme: theme, variant = "default", styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ActionHeaderProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "grid",
    gridTemplateColumns: "minmax(min-content, 1fr) auto minmax(min-content, 1fr)",
    alignItems: "center",
    overflowX: "auto",
    scrollbarWidth: "none",
    width: "100%",
    height: theme.toRem(40),
    padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[8])}`,
    gap: theme.toRem(theme.spacing[12]),
    borderBottom: `${theme.divider.default.border.width} solid ${theme.divider.default.color.default}`,

    [`.${ActionHeaderClasses.leading}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "flex-start",
      gap: theme.toRem(theme.spacing[16]),
      whiteSpace: "nowrap",
      ...styleSlots?.leading,
    },

    [`.${ActionHeaderClasses.center}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      gap: theme.toRem(theme.spacing[16]),
      whiteSpace: "nowrap",
      ...styleSlots?.center,
    },

    [`.${ActionHeaderClasses.trailing}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "flex-end",
      gap: theme.toRem(theme.spacing[16]),
      whiteSpace: "nowrap",
      ...styleSlots?.trailing,
    },

    [`.${ActionHeaderClasses.divider}`]: {
      display: "flex",
      alignItems: "center",
      height: theme.toRem(24),
      ...styleSlots?.divider,
    },

    [`.${ActionHeaderClasses.status}`]: {
      ...theme.typography.body.smAccent,
      color: theme.color.content.weak,
      ...styleSlots?.status,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledActionHeader = styled("header", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ActionHeaderProps>((props) => generateStyles(props));
